def assign_legacy_records_to_only_user(apps, schema_editor):
    """Preserve legacy data when its sole account makes ownership unambiguous."""
    user_app, user_model = settings.AUTH_USER_MODEL.split(".")
    User = apps.get_model(user_app, user_model)
    users = list(User.objects.order_by("pk").values_list("pk", flat=True)[:2])
    if len(users) != 1:
        return

    owner_id = users[0]
    for model_name in TENANT_MODELS:
        model = apps.get_model("myos_app", model_name)
        model.objects.filter(user__isnull=True).update(user_id=owner_id)


